(() => {
const $=s=>document.querySelector(s),buttons=[...document.querySelectorAll('[data-pose]')];if(!buttons.length)return;
let pose=1,started=0,timer=0,quick=0,alert=false,audio=null,osc=null;
function quiet(){if(osc){osc.stop();osc=null;}}
function sound(){quiet();if(!$('#posture-sound').checked)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();osc=audio.createOscillator();const gain=audio.createGain();osc.frequency.value=180;gain.gain.value=.035;osc.connect(gain).connect(audio.destination);osc.start();}catch{}}
function render(){const seconds=pose===1?0:Math.min(10,(performance.now()-started)/1000);$('#posture-seconds').textContent=Math.floor(seconds);$('.posture-timer').setAttribute('aria-valuenow',seconds.toFixed(1));$('.posture-timer i').style.width=seconds*10+'%';if(seconds>=10&&!alert){alert=true;$('.posture-lab').classList.add('is-alert');$('#posture-result').textContent='Time to sit upright.';$('#posture-explain').textContent='The slouch has lasted 10 seconds. AlignR gives a cue until you sit upright.';sound();clearInterval(timer);}}
function choose(n,isQuick=false){clearInterval(timer);clearTimeout(quick);quiet();pose=n;alert=false;$('.posture-lab').classList.remove('is-alert');buttons.forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.pose)===n)));const label=buttons.find(b=>Number(b.dataset.pose)===n).textContent.trim();$('#posture-person').src='assets/alignr-pose-'+n+'.png';$('#posture-person').alt=label+' sitting illustration from the project documentation';started=performance.now();$('#posture-result').textContent=n===1?'Upright. All quiet.':isQuick?'A quick bend.':'Slouched. Counting…';$('#posture-explain').textContent=n===1?'Choose a slouched position to start the timer.':isQuick?'Back upright in 3 seconds — too brief to trigger a cue.':'Stay here for 10 seconds, or sit upright to clear the timer.';render();if(n!==1)timer=setInterval(render,100);if(isQuick)quick=setTimeout(()=>{choose(1);$('#posture-result').textContent='Brief movement. No alert.';$('#posture-explain').textContent='Returning upright after 3 seconds cleared the timer.';},3000);}
buttons.forEach(b=>b.addEventListener('click',()=>choose(Number(b.dataset.pose))));$('#posture-bend').addEventListener('click',()=>choose(2,true));$('#posture-reset').addEventListener('click',()=>choose(1));$('#posture-sound').addEventListener('change',()=>{if(alert)sound();else quiet();});document.addEventListener('visibilitychange',()=>{if(document.hidden)choose(1);});window.addEventListener('pagehide',quiet);
const parts=['mpu','uno','oled','buzz'];$('#circuit-next')?.addEventListener('click',()=>{const active=$('.dl-part-chip.active'),i=parts.indexOf(active?.dataset.part);$('.dl-part-chip[data-part="'+parts[(i+1)%parts.length]+'"]').click();});choose(1);
})();
